import sys
def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1]); x = int(data[2])
    cnt = [0] * (n + 1); opn = [0] * (n + 1)
    for i in range(m):
        v = int(data[3 + 2 * i]); s = data[4 + 2 * i]
        cnt[v] += 1
        if s == b"0":
            opn[v] += 1
    others = [(cnt[y], opn[y]) for y in range(1, n + 1) if y != x and cnt[y] > 0]
    total_open = sum(o for _, o in others)
    cx = cnt[x]
    def feasible(k):
        need_sum = 0
        limit = cx + k
        for c, o in others:
            need = c - limit + 1
            if need > 0:
                if need > o:
                    return False
                need_sum += need
                if need_sum > k:
                    return False
        return True
    lo, hi = 0, total_open
    if not feasible(hi):
        print(-1); return
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)
main()

